        {{ mfg_trace_re_extract("trim(coalesce(limits_text, ''))", "^([<>=!≤≥]+)\\s*([-+]?(?:\\d+\\.?\\d*|\\.\\d+)(?:[eE][-+]?\\d+)?)\\s*([A-Za-zµμΩ°%/^\\-\\d]*[A-Za-zµμΩ°%])?$", 3) }} as limits_comparator_unit,
