stated as (
    select
        extracted.*,
        case
            when coalesce(limits_tolerance_center, '') <> '' then cast(null as varchar)
            when coalesce(limits_comparator_op, '') <> '' then nullif(trim(limits_comparator_op), '')
            when coalesce(limits_number_value, '') <> '' then cast(null as varchar)
            else cast(null as varchar)
        end as op_text
    from extracted
)

select
