from stated
where op_text is not null
  and {% if var('mfg_trace_comparators') %}case{% for row in var('mfg_trace_comparators') %}
          when op_text = '{{ row['text'] | trim | replace("'", "''") }}' then '{{ row['code'] | replace("'", "''") }}'{% endfor %}
